    (F : bvmap 5 word) fc (m : word -> option byte) (lo : Z),
  stk rsegs m lo (bv_unsigned sp) ->
  rw_cells rsegs m PGOT_FINI [C8 (Z_to_bv 64 0x2a498); C8 (Z_to_bv 64 PFINI_ARRAY)] ->   (* [comment removed for export] *)
  rw_cells rsegs m PFINI_ARRAY [C8 (Z_to_bv 64 0x12d10)] ->                              (* [comment removed for export] *)
  rw_cells rsegs m PFINALIZED [C1 (Z_to_bv 8 0)] ->                                      (* [comment removed for export] *)
  rw_cells rsegs m PGOT_CXA [C8 (Z_to_bv 64 0x21810); C8 z64] ->                          (* [comment removed for export] *)
  rw_cells rsegs m PDSO_HANDLE [C8 (Z_to_bv 64 PDSO_HANDLE)] ->                          (* [comment removed for export] *)
  mem_inv rsegs m ->
  (lo <= bv_unsigned sp - 48)%Z -> (0x5d000 <= lo)%Z ->
  evt rsegs (plibc_exit_fini_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
